Rules.InvariantScript:
Concurrent(
    ClearCollect(
        colLandLeaseSubaccounts,
        Sort(
            AddColumns(
                'Land Lease Subaccounts',
                IsFolded,
                true
            ),
            Order,
            SortOrder.Ascending
        )
    );
    ,
    ClearCollect(
        colLandLeaseProjectCosts,
        Filter(
            'Land Lease Project Costs',
            Project.Project = gblSelectedProject.Project
        )
    );
    ClearCollect(
        colLandLeasePeriods,
        Filter(
            'Land Lease Periods',
            'Project Cost'.'Land Lease Project Cost' in colLandLeaseProjectCosts.'Land Lease Project Cost'
        )
    );
    ,
    ClearCollect(
        colGeneratorsInProject,
        AddColumns(
            Filter(
                GeneratorInProjects,
                AsType(
                    ModuleTypeInProject,
                    GeneratorTypeInProjects
                ).Project.Project = gblSelectedProject.Project
            ),
            Label,
            $"{Name} - {Status}",
            Order,
            Value(
                Last(
                    Split(
                        Name,
                        "_"
                    )
                ).Value
            )
        )
    );
    Collect(
        colGeneratorsInProject,
        AddColumns(
            Filter(
                GeneratorInProjects,
                AsType(
                    ModuleTypeInProject,
                    PVModuleTypeInProjects
                ).Project.Project = gblSelectedProject.Project
            ),
            Label,
            AsType(
                ModuleTypeInProject,
                PVModuleTypeInProjects
            ).Label
        )
    );
    ,
    ClearCollect(
        colAllocatedWtgsInSelectedLandLeaseCost,
        Blank()
    );

)

