Rules.InvariantScript:
UpdateIf(
     colLandLeaseSubaccounts,
    'Land Lease Subaccount' = gal_LandLease_Content_Subaccounts.Selected.'Land Lease Subaccount',
    {  
        IsFolded: Not(gal_LandLease_Content_Subaccounts.Selected.IsFolded)
    }
);

UpdateIf(
    colLandLeaseSubaccounts,
    'Land Lease Subaccount' = gal_LandLease_Content_Subaccounts.Selected.'Land Lease Subaccount',
    {IsFolded: Not(gal_LandLease_Content_Subaccounts.Selected.IsFolded)}
);

Table(
    {
        ItemKey: "newLandLeaseContractKey",
        ItemDisplayName: "Add Contract Type",
        ItemIconName: "Add",
        ItemEnabled: And(
            DataSourceInfo(
                'Land Lease Project Costs',
                DataSourceInfo.CreatePermission
            ),
            If(
                locSelectedLandLeaseSubaccount.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount',
                IsBlank(locSelectedLandLeasePeriod),
                true
            ),
            IsBlank(
                LookUp(
                    'Land Lease Project Costs',
                    And(
                        Project.Project = gblSelectedProject.Project,
                        'Is Standard Contract?' = 'Is Standard Contract? (Land Lease Project Costs)'.Yes,
                        Subaccount.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount'
                    )
                )
            )
        )
    },
    {
        ItemKey: "newLandLeasePeriodKey",
        ItemDisplayName: "Add Period",
        ItemIconName: "Add",
        ItemEnabled: And(
            DataSourceInfo(
                'Land Lease Periods',
                DataSourceInfo.CreatePermission
            ),
            Not(locSelectedLandLeaseCost.'Is Standard Contract?' = 'Is Standard Contract? (Land Lease Project Costs)'.Yes),
            Not(
                StartsWith(
                    locSelectedLandLeasePeriod.Name,
                    "Standard"
                )
            ),
            Not(IsBlank(locSelectedLandLeasePeriod)),
            Not(IsBlank(locSelectedLandLeaseCost)),
            locSelectedLandLeaseSubaccount.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount',
            With(
                {
                    varLandLeasePeriods: Sort(
                        Filter(
                            colLandLeasePeriods,
                            'Project Cost'.'Land Lease Project Cost' = locSelectedLandLeaseCost.'Land Lease Project Cost'
                        ),
                        Period
                    )
                },
                With(
                    {
                        varLastLandLeasePeriod: Last(varLandLeasePeriods),
                        varFirstLandLeasePeriod: First(varLandLeasePeriods)
                    },
                    And(
                        locSelectedLandLeasePeriod.'Land Lease Period' = varLastLandLeasePeriod.'Land Lease Period',
                        Or(
                            Not(IsBlank(varFirstLandLeasePeriod.'Fixed Costs')),
                            Not(IsBlank(varFirstLandLeasePeriod.'% of Revenues')),
                            Not(IsBlank(varFirstLandLeasePeriod.'EUR/MW')),
                            Not(IsBlank(varFirstLandLeasePeriod.'EUR/MWh')),
                            Not(IsBlank(varFirstLandLeasePeriod.'EUR/WTG'))
                        )
                    )
                )
            )
        )
    },
    {
        ItemKey: "AddLandLeaseStandardContractKey",
        ItemDisplayName: "Add Standard Contract",
        ItemIconName: "Add",
        ItemEnabled: And(
            Not(
                IsBlank(
                    LookUp(
                        'OPEX & Land Lease Standard Assumptions',
                        And(
                            Country.Country = gblSelectedProject.Country.Country,
                            Technology = gblSelectedProject.Technology,
                            'Type Of Contract' = 'Contract Types'.Landlease,
                            'Land Lease Subaccount'.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount'
                        )
                    )
                )
            ),
            IsBlank(
                LookUp(
                    'Land Lease Project Costs',
                    And(
                        Project.Project = gblSelectedProject.Project,
                        'Is Standard Contract?' = 'Is Standard Contract? (Land Lease Project Costs)'.Yes,
                        Subaccount.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount'
                    )
                )
            ),
            IsBlank(
                LookUp(
                    'Land Lease Project Costs',
                    And(
                        Project.Project = gblSelectedProject.Project,
                        //'Is Standard Contract?' = 'Is Standard Contract? (Land Lease Project Costs)'.Yes,
                        Subaccount.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount'
                    )
                )
            )
        )
    },
    {
        ItemKey: "EditLandLeasePeriodKey",
        ItemDisplayName: "Edit",
        ItemIconName: "Edit",
        ItemEnabled: And(
            Not(IsBlank(locSelectedLandLeasePeriod)),
            RecordInfo(
                locSelectedLandLeasePeriod,
                RecordInfo.EditPermission
            ),
            locSelectedLandLeaseSubaccount.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount',
            Not(locSelectedLandLeaseCost.'Is Standard Contract?' = 'Is Standard Contract? (Land Lease Project Costs)'.Yes),
            Not(
                StartsWith(
                    locSelectedLandLeasePeriod.Name,
                    "Standard"
                )
            )
        )
    },
    {
        ItemKey: "deleteLandLeasePeriodKey",
        ItemDisplayName: "Delete",
        ItemIconName: "Delete",
        ItemEnabled: And(
            Not(IsBlank(locSelectedLandLeasePeriod)),
            RecordInfo(
                locSelectedLandLeasePeriod,
                RecordInfo.DeletePermission
            ),
            locSelectedLandLeaseSubaccount.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount',
            If(
                StartsWith(
                    Lower(locSelectedLandLeasePeriod.Name),
                    "standard"
                ),
                locSelectedLandLeasePeriod.Period = 'Land Lease Period'.'Period 1',
                Or(
                    locSelectedLandLeasePeriod.Period = 'Land Lease Period'.'Period 1',
                    With(
                        {
                            locLastPeriod: Last(
                                Sort(
                                    Filter(
                                        colLandLeasePeriods,
                                        'Project Cost'.'Land Lease Project Cost' = locSelectedLandLeasePeriod.'Project Cost'.'Land Lease Project Cost'
                                    ),
                                    Name,
                                    SortOrder.Ascending
                                )
                            )
                        },
                        locLastPeriod.'Land Lease Period' = locSelectedLandLeasePeriod.'Land Lease Period'
                    )
                )
            )
        )
    }
)

Switch(
    Self.Selected.ItemKey,
    "newLandLeaseContractKey",
    Clear(colAllocatedWtgsInSelectedLandLeaseCost);
    UpdateContext(
        {
            locSelectedLandLeasePeriod: Blank(),
            locSelectedLandLeaseCost: Blank(),
            locShowSecondPayment: false,
            locShowThirdPayment: false,
            locRightPanelState: "New",
            locSelectedLandLeaseSubaccount: gal_LandLease_Content_Subaccounts.Selected,
            locNewPeriodDesc: Blank(),
            locParentLandLeasePeriod: Blank(),
            locSelectAllWTG: false,
            locIsVisibleRightPanelNewEditPeriod: true
        }
    );
    UpdateContext(
        {
            locCODDate: gblSelectedProject.'Operations start date (COD)',
            locIsStartDateStandardAssumption: 'IsStartDateStandardAssumption (Land Lease Project Costs)'.No,
            locResetStartDate: true
        }
    ),
    "AddLandLeaseStandardContractKey",
        //LoadLandLeaseStandardContractsAndPeriods
    UpdateContext(
        {
            locIsVisiblePopUpSpinner: true,
            locSpinnerInformationText: "Please wait, loading Standard Assumption Contract..."
        }
    );
    Clear(colLoadLandLeasePeriods);
    Clear(colLandLeaseStandardAssumptionContract);
    With(
        {
            recFilteredStandardContractsForProject: Filter(
                'Land Lease Project Costs',
                And(
                    Project.Project = gblSelectedProject.Project,
                    'Is Standard Contract?' = 'Is Standard Contract? (Land Lease Project Costs)'.Yes,
                    Subaccount.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount'
                )
            ),
            recCountryTechnologyRelatedStandardAssumption: Sort(
                Filter(
                    'OPEX & Land Lease Standard Assumptions',
                    And(
                        Country.Country = gblSelectedProject.Country.Country,
                        Technology = gblSelectedProject.Technology,
                        'Type Of Contract' = 'Contract Types'.Landlease,
                        'Land Lease Subaccount'.'Land Lease Subaccount' = ThisItem.'Land Lease Subaccount'
                    )
                ),
                Description,
                SortOrder.Ascending
            ),
            recCODDate: gblSelectedProject.'Operations start date (COD)',
            recCODYear: Year(gblSelectedProject.'Operations start date (COD)') + 1
        },
        If(
            CountRows(recFilteredStandardContractsForProject) = 0,
            With(
                {
                    recSortedCountryTechnologyStandardAssumptions: recCountryTechnologyRelatedStandardAssumption,
                    recStandardAssumptionContracts: Filter(
                        recCountryTechnologyRelatedStandardAssumption,
                        Period = 'Opex & Land Lease Period'.'Period 1'
                    )
                },
                ForAll(
                    recStandardAssumptionContracts,
                    With(
                        {StandardAssumptionContractRecord: ThisRecord},
                        Collect(
                            colLandLeaseStandardAssumptionContract,
                            Patch(
                                'Land Lease Project Costs',
                                Defaults('Land Lease Project Costs'),
                                {
                                    Project: gblSelectedProject,
                                    Subaccount: StandardAssumptionContractRecord.'Land Lease Subaccount',
                                    Name: gblSelectedProject.'Project Name' & "-" & StandardAssumptionContractRecord.'Land Lease Subaccount'.Name & "-" & StandardAssumptionContractRecord.Name,
                                    Description: StandardAssumptionContractRecord.Description,
                                    Currency: StandardAssumptionContractRecord.Currency,
                                    'Due Date One-Time Payment': StandardAssumptionContractRecord.'Due Date One-Time Payment',
                                    'Amount One-Time Payment': Value(
                                        Text(
                                            StandardAssumptionContractRecord.'Amount One-Time Payment',
                                            "##0.00"
                                        )
                                    ),
                                    Secured: If(
                                        StandardAssumptionContractRecord.Secured = 'Secured (OPEX & Land Lease Standard Assumptions)'.Yes,
                                        'Land Lease Secured'.Yes,
                                        'Land Lease Secured'.No
                                    ),
                                    'Owning Business Unit': gblSelectedProject.'Besitzer (Unternehmenseinheit)',
                                    'Due Date One-Time Payment 2': StandardAssumptionContractRecord.'Due Date One-Time Payment 2',
                                    'Amount One-Time Payment 2': Value(
                                        Text(
                                            StandardAssumptionContractRecord.'Amount One-Time Payment 2',
                                            "##0.00"
                                        )
                                    ),
                                    'Due Date One-Time Payment 3': StandardAssumptionContractRecord.'Due Date One-Time Payment 3',
                                    'Amount One-Time Payment 3': Value(
                                        Text(
                                            StandardAssumptionContractRecord.'Amount One-Time Payment 3',
                                            "##0.00"
                                        )
                                    ),
                                    AllWTGAllocated: If(
                                        StandardAssumptionContractRecord.AllWTGAllocated = 'AllWTGAllocated (OPEX & Land Lease Standard Assumptions)'.Yes,
                                        'AllWTGAllocated (Land Lease Project Costs)'.Yes,
                                        'AllWTGAllocated (Land Lease Project Costs)'.No
                                    ),
                                    'Use Inflation Profile': If(
                                        StandardAssumptionContractRecord.'Use Inflation Profile' = 'Use Inflation Profile (OPEX & Land Lease Standard Assumptions)'.Yes,
                                        'Use Inflation Profile (Land Lease Project Costs)'.Yes,
                                        'Use Inflation Profile (Land Lease Project Costs)'.No
                                    ),
                                    'Use Country Inflation Profile': If(
                                        StandardAssumptionContractRecord.'Use Country Inflation Profile' = 'Use Country Inflation Profile (OPEX & Land Lease Standard Assumptions)'.Yes,
                                        'Use Country Inflation Profile (Land Lease Project Costs)'.Yes,
                                        'Use Country Inflation Profile (Land Lease Project Costs)'.No
                                    ),
                                    'Inflation Country Area': StandardAssumptionContractRecord.'Inflation Country Area',
                                    'Inflation Profile': Switch(
                                        true,
                                        And(
                                            StandardAssumptionContractRecord.'Use Inflation Profile' = 'Use Inflation Profile (OPEX & Land Lease Standard Assumptions)'.Yes,
                                            StandardAssumptionContractRecord.'Use Country Inflation Profile' = 'Use Country Inflation Profile (OPEX & Land Lease Standard Assumptions)'.Yes
                                        ),
                                        LookUp(
                                            'Country Inflation Profiles',
                                            Country.Country = gblSelectedProject.Country.Country && Year = recCODYear
                                        ).Inflation,
                                        And(
                                            StandardAssumptionContractRecord.'Use Inflation Profile' = 'Use Inflation Profile (OPEX & Land Lease Standard Assumptions)'.Yes,
                                            StandardAssumptionContractRecord.'Use Country Inflation Profile' = 'Use Country Inflation Profile (OPEX & Land Lease Standard Assumptions)'.No
                                        ),
                                        StandardAssumptionContractRecord.'Inflation Profile',
                                        Blank()
                                    ),
                                    'Inflation Start Year': recCODYear,
                                    IsStartDateStandardAssumption: 'IsStartDateStandardAssumption (Land Lease Project Costs)'.Yes,
                                    'Is Standard Contract?': 'Is Standard Contract? (Land Lease Project Costs)'.Yes
                                }
                            )
                        );
                        If(
                            StandardAssumptionContractRecord.AllWTGAllocated = 'AllWTGAllocated (OPEX & Land Lease Standard Assumptions)'.Yes,
                            ForAll(
                                colGeneratorsInProject As recGeneratorInProject,
                                With(
                                    {
                                        recLandLeaseContractCost: LookUp(
                                            colLandLeaseStandardAssumptionContract,
                                            'Land Lease Subaccount'.'Land Lease Subaccount' = StandardAssumptionContractRecord.'Land Lease Subaccount'.'Land Lease Subaccount'
                                        )
                                    },
                                    Patch(
                                        'Land Lease Allocation WTGS',
                                        Defaults('Land Lease Allocation WTGS'),
                                        {
                                            Name: recLandLeaseContractCost.'Land Owner' & "-" & StandardAssumptionContractRecord.Description & "-" & recGeneratorInProject.Name,
                                            'Project Cost': recLandLeaseContractCost,
                                            'Generator In Project': recGeneratorInProject,
                                            'Owning Business Unit': gblSelectedProject.'Besitzer (Unternehmenseinheit)'
                                        }
                                    )
                                )
                            )
                        )
                    )
                );
                ForAll(
                    recSortedCountryTechnologyStandardAssumptions,
                    With(
                        {
                            recStandardAssumptionRecord: ThisRecord,
                            recLandLeaseSubAccountID: ThisRecord.'Land Lease Subaccount'.'Land Lease Subaccount'
                        },
                        If(
                            recStandardAssumptionRecord.Period = 'Opex & Land Lease Period'.'Period 1',
                            RemoveIf(
                                colLoadLandLeasePeriods,
                                true
                            )
                        );
                        With(
                            {
                                recProjectCost: LookUp(
                                    colLandLeaseStandardAssumptionContract,
                                    And(Subaccount.'Land Lease Subaccount' = recLandLeaseSubAccountID)
                                ),
                                recStartDate: Switch(
                                    recStandardAssumptionRecord.Period,
                                    'Opex & Land Lease Period'.'Period 1',
                                    recCODDate,
                                    DateAdd(
                                        Last(
                                            Sort(
                                                colLoadLandLeasePeriods,
                                                Period,
                                                SortOrder.Ascending
                                            )
                                        ).'Start Date',
                                        Value(
                                            Last(
                                                Sort(
                                                    colLoadLandLeasePeriods,
                                                    Period,
                                                    SortOrder.Ascending
                                                )
                                            ).'Land Lease duration years'
                                        ) * 12 + Value(
                                            Last(
                                                Sort(
                                                    colLoadLandLeasePeriods,
                                                    Period,
                                                    SortOrder.Ascending
                                                )
                                            ).'Land Lease duration months'
                                        ),
                                        TimeUnit.Months
                                    )
                                )
                            },
                            Collect(
                                colLoadLandLeasePeriods,
                                Patch(
                                    'Land Lease Periods',
                                    Defaults('Land Lease Periods'),
                                    {
                                        'Project Cost': recProjectCost,
                                        Name: recStandardAssumptionRecord.Description,
                                        Period: Switch(
                                            recStandardAssumptionRecord.Period,
                                            'Opex & Land Lease Period'.'Period 1',
                                            'Land Lease Period'.'Period 1',
                                            'Opex & Land Lease Period'.'Period 2',
                                            'Land Lease Period'.'Period 2',
                                            'Opex & Land Lease Period'.'Period 3',
                                            'Land Lease Period'.'Period 3',
                                            'Opex & Land Lease Period'.'Period 4',
                                            'Land Lease Period'.'Period 4',
                                            'Opex & Land Lease Period'.'Period 5',
                                            'Land Lease Period'.'Period 5',
                                            'Opex & Land Lease Period'.'Period 6',
                                            'Land Lease Period'.'Period 6',
                                            'Opex & Land Lease Period'.'Period 7',
                                            'Land Lease Period'.'Period 7',
